def chunk_overlap(text: str, max_len: int, overlap: int) -> list:
    """把文本切成有重叠的分段。
    每段不超过 max_len 字符；相邻段之间重叠 overlap 个字符；
    最后一段即使很短也要保留。
    """
    if not text:
        return []

    chunks = []
    start = 0
    while start < len(text):
        end = min(start + max_len, len(text))
        if start == 0:
            chunks.append(text[:end])
        else:
            chunks.append(text[start - overlap:end])
        start = end

    return chunks

